+
+test("consume uses the batch that expires first (FEFO)", () => {
+  const store = fresh();
+  // Milk: lot HD-1026 (id 3) received later, HD-1022 (id 4) expires first.
+  const used = consume(store, 2, 3, { at, ref: "recipe:bechamel" });
+  assert.deepEqual(used, [
+    { batchId: 4, qty: 2 },
+    { batchId: 3, qty: 1 },
+  ]);
+});
+
+test("batches without expiry are used last, ties go to the earlier receipt then lower id", () => {
+  const store = fresh();
+  store.data.batches.push(
+    { id: 100, itemId: 2, lot: "NO-EXP", qty: 5, receivedOn: "2026-10-01", expires: null, location: "fridge" },
+    { id: 101, itemId: 2, lot: "SAME-B", qty: 1, receivedOn: "2026-10-21", expires: "2026-10-29", location: "fridge" },
+    { id: 102, itemId: 2, lot: "SAME-C", qty: 1, receivedOn: "2026-10-21", expires: "2026-10-29", location: "fridge" },
+  );
+  const used = consume(store, 2, 15, { at });
+  assert.deepEqual(used.map((u) => u.batchId), [101, 102, 4, 3, 100]);
+});
